insert into public.brands (name, slug, description, banner_url, is_featured, sort_order, is_sample) values ('Atelier Mira', 'atelier-mira', 'Fluid womenswear in satin, georgette and fine cotton. Atelier Mira designs in small seasonal drops and cuts every piece to move.', 'https://images.unsplash.com/photo-1779406165962-7df12de281b1?ar=16:9&fit=crop&w=1200&q=80&auto=format', true, 1, true);
